package dev.irisvisualizer.editor;

import java.io.IOException;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.Properties;
import java.util.function.Function;

/** Native canopy authoring; never constructs foliage or branch geometry. */
public final class ProceduralCanopies {
    public static final List<String> OBJECT_FIELDS = List.of("canopy");
    public static final List<String> CANOPY_FIELDS = List.of("startAngle", "squish", "mode", "leafDensity", "crownStretchX", "crownStretchZ", "layers", "branches");
    public static final List<String> LAYER_FIELDS = List.of("yOffset", "radius");
    public static final List<String> BRANCH_FIELDS = List.of("probabilityFunction", "probabilityConstant", "probabilityBase", "probabilityCrown", "probabilitySteepness", "probabilityMidpoint", "probabilityExponent", "probabilityMean", "probabilityStd", "probabilityScale", "probabilityPeriods", "lengthFunction", "lengthBase", "lengthCrown", "lengthConstant", "lengthMax", "lengthSteepness", "azimuthMode", "azimuth", "elevation", "sag", "branchDepth", "leafStartUp", "clusterRadius", "clusterMode", "clusterDensity", "subBranches");
    public static final List<String> SUB_BRANCH_FIELDS = List.of("count", "pitchDelta", "yawDelta", "lengthScale", "sag", "clusterRadius", "clusterMode", "clusterDensity");
    private static final Properties DATA=new Properties();
    static { try (var input=ProceduralCanopies.class.getResourceAsStream("/procedural-canopy-fields.properties")) { if (input==null) throw new IOException("Missing pinned canopy contracts");DATA.load(input);if (!"explicitNonemptyElseProfile".equals(DATA.getProperty("layers.policy")) || !"disabled".equals(DATA.getProperty("execution.policy"))) throw new IOException("Unsupported canopy policy"); } catch (IOException failure) { throw new ExceptionInInitializerError(failure); } }
    public record Context(ProceduralObjects.Context owner,String scope,int layer) {
        public Context { if (owner==null || !owner.kind().equals("trees") || scope==null || !List.of("canopy","canopy.branches","canopy.branches.subBranches","canopy.layers").contains(scope) || (scope.equals("canopy.layers") ? layer<0 : layer!=-1)) throw new IllegalArgumentException("Select a procedural tree canopy owner"); }
        public static Context object(ProceduralObjects.Context owner,String scope) { return new Context(owner,scope,-1); }
        public static Context layer(ProceduralObjects.Context owner,int layer) { return new Context(owner,"canopy.layers",layer); }
        public boolean layerEntry() { return scope.equals("canopy.layers"); }
        public String group() { return layerEntry() ? "layers" : scope.substring(scope.lastIndexOf('.')+1); }
        public String prefix() { return owner.prefix()+scope+(layerEntry() ? "."+layer : "")+"."; }
    }
    private static void tree(String path,ProceduralObjects.Context owner) { if (owner==null || !owner.kind().equals("trees")) throw new IllegalArgumentException("Select a procedural tree");ProceduralObjects.authorize(path,owner); }
    private static void authorize(String path,Context c) { if (c==null) throw new IllegalArgumentException("Select a canopy context");tree(path,c.owner()); }
    public static List<String> fields(Context c) { return switch(c.group()) { case "canopy" -> CANOPY_FIELDS;case "layers" -> LAYER_FIELDS;case "branches" -> BRANCH_FIELDS;case "subBranches" -> SUB_BRANCH_FIELDS;default -> throw new IllegalArgumentException("Select a canopy scope"); }; }
    private static void field(Context c,String field) { if (field==null || !fields(c).contains(field)) throw new IllegalArgumentException("Select a canopy field"); }
    static String property(Context c,String field,String key) { field(c,field);return DATA.getProperty(c.group()+"."+field+"."+key); }
    public static List<String> scalars(Context c) { return fields(c).stream().filter(f -> !List.of("layers","branches","subBranches").contains(f)).toList(); }
    private static void scalar(Context c,String field) { field(c,field);if (!scalars(c).contains(field)) throw new IllegalArgumentException("Use the nested owner/list controls"); }
    public static String help(Context c,String field) { return property(c,field,"description"); }
    public static String type(Context c,String field) { scalar(c,field);return property(c,field,"type"); }
    public static String defaultValue(Context c,String field) { scalar(c,field);return property(c,field,"default"); }
    public static List<String> choices(Context c,String field) { scalar(c,field);String items=property(c,field,"choices");return items==null ? List.of() : List.of(items.split(",")); }
    public static String choiceHelp(Context c,String field,String choice) { return property(c,field,choice+".description"); }
    public static String constraints(Context c,String field) { String min=property(c,field,"minimum"),max=property(c,field,"maximum");return (type(c,field).equals("int") ? "Exact signed 32-bit integer" : "Finite number")+(min==null ? "" : "; minimum "+min)+(max==null ? "" : "; maximum "+max); }
    private static LosslessJson inline(LosslessJson parent,String member) { String token=parent.token(member);return token==null || token.equals("null") ? null : new LosslessJson(token.getBytes(StandardCharsets.UTF_8)); }
    private static LosslessJson parent(LosslessJson entry,Context c) { String[] parts=c.scope().split("\\.");LosslessJson current=entry;for (int i=0;i<parts.length-1;i++) { current=inline(current,parts[i]);if (current==null) throw new IllegalArgumentException("Enable each inline canopy ancestor first"); }return current; }
    private static List<LosslessJson> layerEntries(LosslessJson canopy) { String token=canopy.token("layers");return token==null || token.equals("null") ? null : canopy.objectArray("layers"); }
    private static void limit(List<LosslessJson> rows,boolean adding) { if (rows!=null && (rows.size()>64 || adding && rows.size()>=64)) throw new IllegalArgumentException("Canopy layers have a 64-entry editor limit"); }
    static List<LosslessJson> layers(LosslessJson entry) { var canopy=inline(entry,"canopy");if (canopy==null) throw new IllegalArgumentException("Enable inline canopy first");return layerEntries(canopy); }
    static LosslessJson object(LosslessJson entry,Context c) { if (c.layerEntry()) { var rows=layers(entry);limit(rows,false);if (rows==null || c.layer()>=rows.size()) throw new IllegalArgumentException("Select an existing canopy layer");return rows.get(c.layer()); }String member=c.scope().substring(c.scope().lastIndexOf('.')+1);return inline(parent(entry,c),member); }
    static boolean stored(LosslessJson entry,Context c) { if (c.layerEntry()) return true;String member=c.scope().substring(c.scope().lastIndexOf('.')+1);return parent(entry,c).token(member)!=null; }
    private static byte[] parents(LosslessJson current,String[] parts,int index,Function<LosslessJson,byte[]> op) { if (index==parts.length-1) return op.apply(current);if (inline(current,parts[index])==null) throw new IllegalArgumentException("Enable each inline canopy ancestor first");return current.objectEdit(parts[index],child -> parents(child,parts,index+1,op),false); }
    private static byte[] editParent(byte[] raw,Context c,Function<LosslessJson,byte[]> op) { if (c.layerEntry()) throw new IllegalArgumentException("Use layer lifecycle controls");return ProceduralObjects.edit(raw,c.owner(),entry -> parents(entry,c.scope().split("\\."),0,op)); }
    private static byte[] edit(byte[] raw,Context c,Function<LosslessJson,byte[]> op) { if (c.layerEntry()) return ProceduralObjects.edit(raw,c.owner(),entry -> { object(entry,c);return entry.objectEdit("canopy",canopy -> canopy.objectArrayEdit("layers",c.layer(),op),false); });String member=c.scope().substring(c.scope().lastIndexOf('.')+1);return editParent(raw,c,p -> { if (inline(p,member)==null) throw new IllegalArgumentException("Enable inline canopy settings first");return p.objectEdit(member,op,false); }); }
    public static byte[] enable(String path,byte[] raw,Context c) { authorize(path,c);String member=c.scope().substring(c.scope().lastIndexOf('.')+1);return editParent(raw,c,p -> { if (inline(p,member)!=null) throw new IllegalArgumentException("Canopy owner already exists");return p.enableObject(member); }); }
    public static byte[] reset(String path,byte[] raw,Context c) { authorize(path,c);String member=c.scope().substring(c.scope().lastIndexOf('.')+1);return editParent(raw,c,p -> { inline(p,member);return p.token(member)==null ? p.sourceBytes() : p.removeField(member); }); }
    static String value(LosslessJson object,Context c,String field) { String type=type(c,field),token=object.token(field);if (token==null) return defaultValue(c,field);if (!choices(c,field).isEmpty()) return object.stringToken(field);if (type.equals("boolean")) { if (!List.of("true","false").contains(token)) throw new IllegalArgumentException("Stored flag is not boolean");return token; }try { if (!LosslessJson.numericToken(token)) throw new NumberFormatException();var number=new BigDecimal(token);if (type.equals("int")) number.intValueExact();else if (!Double.isFinite(number.doubleValue())) throw new ArithmeticException();return token; } catch (NumberFormatException | ArithmeticException bad) { throw new IllegalArgumentException("Stored canopy number has unsupported type/width",bad); } }
    public static byte[] set(String path,byte[] raw,Context c,String field,String input) { authorize(path,c);scalar(c,field);if (input==null || input.indexOf(0)>=0) throw new IllegalArgumentException("Enter a supported canopy value");String type=type(c,field);BigDecimal number=null;
        if (!choices(c,field).isEmpty()) { if (!choices(c,field).contains(input)) throw new IllegalArgumentException("Choose a pinned canopy option"); }else if (type.equals("boolean")) { if (!List.of("true","false").contains(input)) throw new IllegalArgumentException("Choose true or false"); }else { try { number=new BigDecimal(input);if (type.equals("int")) number.intValueExact();else if (!Double.isFinite(number.doubleValue()) || number.signum()!=0 && number.doubleValue()==0) throw new ArithmeticException(); } catch (NumberFormatException | ArithmeticException bad) { throw new IllegalArgumentException("Enter a finite canopy number with native width",bad); }String min=property(c,field,"minimum"),max=property(c,field,"maximum");if (min!=null && number.compareTo(new BigDecimal(min))<0 || max!=null && number.compareTo(new BigDecimal(max))>0) throw new IllegalArgumentException(constraints(c,field)); }
        BigDecimal desired=number;return edit(raw,c,o -> { String old=value(o,c,field);if (o.token(field)!=null && (desired!=null ? desired.compareTo(new BigDecimal(old))==0 : old.equals(input))) return o.sourceBytes();if (desired!=null) return type.equals("int") ? o.nullableInteger(field,desired.longValueExact()) : o.token(field)==null ? o.enable(field,desired.toString()) : o.number(field,desired.doubleValue());if (!choices(c,field).isEmpty()) return o.nullableString(field,input);return o.token(field)==null ? o.enable(field,input) : o.bool(field,Boolean.parseBoolean(input)); });
    }
    public static byte[] resetLeaf(String path,byte[] raw,Context c,String field) { authorize(path,c);scalar(c,field);return edit(raw,c,o -> { value(o,c,field);return o.token(field)==null ? o.sourceBytes() : o.removeField(field); }); }
    public static byte[] changeLayers(String path,byte[] raw,ProceduralObjects.Context owner,RiverProfiles.Action action,int index) { tree(path,owner);if (action==null) throw new IllegalArgumentException("Choose a layer action");var c=Context.object(owner,"canopy");return edit(raw,c,canopy -> { var rows=layerEntries(canopy);limit(rows,action==RiverProfiles.Action.ADD || action==RiverProfiles.Action.DUPLICATE);if (action==RiverProfiles.Action.ADD) { if (rows==null) canopy=new LosslessJson(canopy.enableArray("layers"));return canopy.objectArrayInsert("layers",rows==null ? 0 : rows.size(),"{}".getBytes(StandardCharsets.UTF_8)); }if (rows==null || index<0 || index>=rows.size()) throw new IllegalArgumentException("Select an existing canopy layer");if (action==RiverProfiles.Action.REMOVE && rows.size()==1) return canopy.removeField("layers");return BiomeLayers.changeLayers(canopy,"layers",action,index); }); }
    public static byte[] resetLayers(String path,byte[] raw,ProceduralObjects.Context owner) { tree(path,owner);return edit(raw,Context.object(owner,"canopy"),canopy -> { limit(layerEntries(canopy),false);return canopy.token("layers")==null ? canopy.sourceBytes() : canopy.removeField("layers"); }); }
    static List<String> readOnlyPaths(LosslessJson entry,Context c) { var paths=new ArrayList<String>();String prefix=c.layerEntry() ? "canopy.layers["+c.layer()+"]" : c.scope();try { var o=object(entry,c);if (o==null) return List.of();for (String field : o.fields()) { if (c.scope().equals("canopy") && field.equals("branches")) paths.addAll(readOnlyPaths(entry,Context.object(c.owner(),"canopy.branches")));else if (c.scope().equals("canopy.branches") && field.equals("subBranches")) paths.addAll(readOnlyPaths(entry,Context.object(c.owner(),"canopy.branches.subBranches")));else if (c.scope().equals("canopy") && field.equals("layers")) { try { var rows=layers(entry);limit(rows,false);if (rows!=null) for (int i=0;i<rows.size();i++) paths.addAll(readOnlyPaths(entry,Context.layer(c.owner(),i))); } catch (IllegalArgumentException bad) { paths.add("canopy.layers"); } }else if (!scalars(c).contains(field)) paths.add(prefix+"."+field);else try { value(o,c,field); } catch (IllegalArgumentException bad) { paths.add(prefix+"."+field); } } } catch (IllegalArgumentException bad) { paths.add(prefix); }return List.copyOf(paths); }
}
